import{_ as r,l as o,o as e,c as s,v as l,p as n,x as t,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"自投机解码","description":"","frontmatter":{"title":"自投机解码","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/self-speculative-decoding.md","filePath":"llm/self-speculative-decoding.md","lastUpdated":1789023840000}'),h={name:"llm/self-speculative-decoding.md"};function c(E,a,u,f,A,_){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="自投机解码" tabindex="-1">自投机解码 <a class="header-anchor" href="#自投机解码" aria-label="Permalink to &quot;自投机解码&quot;">​</a></h1><div class="epigraph"><p>草稿不必是另一个模型：让目标网络提前退出，用浅层的猜测交给深层一次并行校验，接受规则仍可以对准原分布。</p><footer>—— Zhang et al., Draft &amp; Verify: Lossless Large Language Model Acceleration via Self-Speculative Decoding, ACL 2024；层跳过见 Elhoushi et al., LayerSkip, 2024</footer></div><p><a href="/llm/temperature-reasoning">上一课</a>把温度接到推理路径。加速不能靠把 \\(T\\) 调到 0：贪心只减少随机性，不减少逐步前向次数。<a href="/llm/speculative-decoding">投机解码</a>用第二模型串行猜、目标一次验，无损但要养草稿、要对齐词表与采样。本课补「没有合格小模型」时的路：自投机（self-speculative）让 <em>同一套权重</em> 既当草稿又当目标——典型是浅层提前退出当 \\(q\\)，深层当 \\(p\\)。后课的 Jacobi 连「浅层草稿」也不要，改并行猜未来位置。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>独立草稿的运维成本是真实的：要训、要跟版本、要占显存、还要在连续批里各管一份 KV。很多部署只有一个检查点。缺口是：能否从目标 Transformer 内部挖出一个更快的 \\(q\\)，使 Leviathan 的接受–拒绝仍然成立。Zhang 等人的 Draft &amp; Verify 用层跳过：草稿前向只跑一部分层（其余当恒等或旁路），目标再跑完整层并对草稿 token 做并行校验。Elhoushi 等人的 LayerSkip 把早退训练进网络，使浅层本身更像合法草稿。</p><p>没有训练过早退时，随便跳层会让 \\(q\\) 与 \\(p\\) 差得很远，接受率接近 0，自投机比普通 decode 更慢。本课把「自」限定为 <em>共享权重、可证明无损</em> 的草稿，不把 Medusa 头（另训参数）算进来——那是主干 <a href="/llm/medusa">Medusa</a> 的课。</p><p><span class="marginnote">无损仍相对完整目标分布。浅层输出不是交付物；被拒绝的位置必须用完整 \\(p\\) 的 residual 重采样，与标准投机相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选定草稿深度 \\(d\\)（或一组可跳过的层）。每轮：用 \\(d\\) 层串行生成 \\(\\gamma\\) 个 token，记下 \\(q\\)；再用完整 \\(L\\) 层对这 \\(\\gamma\\) 个位置一次前向，得到 \\(p\\)，按似然比接受。温度、<a href="/llm/logit-bias">logit bias</a>、核必须同时施加于 \\(p\\) 与 \\(q\\)。KV 可以共享：浅层算出的键值对深层往往仍合法，若跳层破坏了残差流，就不能复用，必须分两套缓存——这是自投机相对双模型最容易算错的地方。</p><p>\\(\\gamma\\) 与 \\(d\\) 一起扫。\\(d\\) 太接近 \\(L\\)，草稿不够便宜；\\(d\\) 太小，接受率崩。LayerSkip 用训练把浅层对齐到最终分布，同一 \\(d\\) 下接受率更高，但检查点不再是原预训练权重，评测要声明。</p>',10)),(e(),n(m,null,{default:t(()=>[p(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%B5%85%E5%B1%82%20%2F%20%E8%B7%B3%E5%B1%82%E4%B8%B2%E8%A1%8C%E7%8C%9C%20%CE%B3%22%5D%20--%3E%20V%5B%22%E5%AE%8C%E6%95%B4%E5%B1%82%E4%B8%80%E6%AC%A1%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20V%20--%3E%20A%7B%22%E4%BC%BC%E7%84%B6%E6%AF%94%E6%8E%A5%E5%8F%97%22%7D%0A%20%20A%20--%3E%7C%E6%8B%92%E7%BB%9D%7C%20R%5B%22%E7%94%A8%E5%AE%8C%E6%95%B4%20p%20%E7%9A%84%20residual%20%E9%87%87%E6%A0%B7%22%5D%0A%20%20A%20--%3E%7C%E5%85%A8%E6%8E%A5%E5%8F%97%7C%20B%5B%22%E5%A5%96%E5%8A%B1%20token%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>墙钟公式与标准投机相同：期望前进长度除以「草稿 \\(\\gamma\\) 步 + 一次较胖目标前向」。自投机的 \\(c_{\\mathrm{draft}}\\) 不是另一个模型的步时，而是少跑 \\(L-d\\) 层的步时，通常没有 4B vs 70B 那么悬殊，所以更依赖接受率。带宽墙上，浅层仍要搬那一部分权重；跳过的层没搬，这才是省。若跳过的层很小（只省 MLP 的一部分）而校验仍吃满所有 KV，账可能亏。</p><p><a href="/llm/flashattention">FlashAttention</a> 的 decode 核不关心草稿来自谁，只关心这一拍的查询长度：校验拍 \\(n_q=\\gamma+1\\)，算术强度略升，与普通投机相同。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>自投机不是免费午餐：实现复杂度接近双模型投机，还多了「哪些层可跳、KV 能否共用」的正确性证明。训练过的早退改变模型，不能把 LayerSkip 的加速比写回未改权重的 Draft &amp; Verify。高 \\(T\\) 同样打接受率。结构化掩码必须进 \\(q\\)，否则草稿净猜非法 token。</p><p>出处：Zhang et al., ACL 2024；LayerSkip, Elhoushi et al., 2024。Leviathan et al. ICML 2023 是无损规则的先修，不在本课重推。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自投机用同一权重的浅层当草稿，完整层当目标，接受规则仍无损。</li><li>省的是跳过层的计算与搬移，加速比通常小于独立小草稿。</li><li>KV 能否在深浅层之间共享，要看跳层是否破坏残差；错共用会静默错。</li><li>早退训练提高接受率，但改变检查点。</li><li>采样与约束必须两侧一致。</li><li>后课连浅层草稿也不要，用 Jacobi 并行猜。</li><li>出处：Zhang et al., ACL 2024；Elhoushi et al., LayerSkip, 2024。</li></ul>',8))])}const C=r(h,[["render",c]]);export{g as __pageData,C as default};
